#include <cstddef>

template <typename... Ts>
auto sum(Ts... args)
{
    return (args + ... + 0);
}

template <typename... Ts>
bool allTrue(Ts... args)
{
    return (args && ... && true);
}

template <typename... Ts>
std::size_t count(Ts...)
{
    return sizeof...(Ts);
}

unitTests:
TEST("sum") { CHECK_EQ(sum(1, 2, 3, 4), 10); CHECK_EQ(sum(5), 5); CHECK_EQ(sum(), 0); CHECK_NEAR(sum(1, 2.5), 3.5, 1e-12); }
TEST("allTrue") { CHECK(allTrue(true, true, 1 < 2)); CHECK(!allTrue(true, false, true)); CHECK(allTrue()); }
TEST("count") { CHECK_EQ(count(), 0u); CHECK_EQ(count(1, "two", 3.0), 3u); }

